import argparse
import json
from pathlib import Path


def boxes(root):
    for box in sorted(root.iterdir()):
        if box.name.startswith('.') or box.name == 'teams' or not box.is_dir() or box.is_symlink():
            continue
        inbox = box / 'inbox'
        if inbox.is_dir() and not inbox.is_symlink():
            yield box


def letters(root):
    for box in boxes(root):
        inbox = box / 'inbox'
        for folder in (inbox, inbox / 'done'):
            if folder.is_symlink():
                continue
            for p in sorted(folder.glob('*.md')):
                if p.name.startswith('.') or not p.is_file() or p.is_symlink():
                    continue
                lines = p.read_text().splitlines()
                if not lines or lines[0] != '---' or '---' not in lines[1:]:
                    continue
                end = lines[1:].index('---') + 1
                data = dict(line.split(': ', 1) for line in lines[1:end] if ': ' in line)
                yield box.name, data


def summarize(root):
    all_letters = [data for person, data in letters(root)]
    resolved = {data.get('re') for data in all_letters if data['status'] in ('DONE', 'BLOCKED', 'NEEDS-USER', 'FAILED')}
    opened = sorted(data['id'] for data in all_letters if data['status'] == 'REQUEST' and data['id'] not in resolved)
    return dict(v=1, open=opened)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('node', type=Path)
    a = ap.parse_args()
    if not a.node.is_dir():
        return 2
    print(json.dumps(summarize(a.node), ensure_ascii=False))
    return 0
